(36061, 'Job 40:24', 'Job', 40, 24, 'څوک دا د کُنډو سره راوچتولے شى، يا يې څوک په پوزه کښې د قابو کولو دپاره پېزوان اچولے شى؟', 'چوک دا د کندو سره راوچتولے شی، یا یې چوک په پوزه کشې د قابو کولو دپاره پېزوان اچولے شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_40_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36062, 'Songofsongs 6:1', 'Songofsongs', 6, 1, 'ستا جانان چرته لاړونه، په ټولو پېغلو کښې ښائسته جينۍ؟ ستا جانان چرته تلے دېنه؟ چې مونږ تا سره د هغۀ تلاش وکړونه؟ محبوبه', 'ستا جانان چرته لارونه، په تولو پېغلو کشې شایسته جینی؟ ستا جانان چرته تلے دېنه؟ چې مونز تا سره د هغۀ تلاش وکرونه؟ محبوبه', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36063, 'Songofsongs 6:2', 'Songofsongs', 6, 2, 'زما جانان خپل باغ ته راغلے دېنه، خپل د خوشبويانو کټ ته، چې خپله رمه په باغونو کښې وڅروينه، او د لاله ګلونه ترې نه راټول کړينه.', 'زما جانان خپل باغ ته راغلے دېنه، خپل د خوشبویانو کت ته، چې خپله رمه په باغونو کشې وچروینه، او د لاله ګلونه ترې نه راتول کرینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36064, 'Songofsongs 6:3', 'Songofsongs', 6, 3, 'جانان زما او زۀ د جانان يمه، هغه چې د لاله په ګلونو کښې مزې کوينه.', 'جانان زما او زۀ د جانان یمه، هغه چې د لاله په ګلونو کشې مزې کوینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36065, 'Songofsongs 6:4', 'Songofsongs', 6, 4, 'زما محبوبې، تۀ لکه د تِرضاه د ښار په شان ښائسته ينه. آو، لکه د يروشلم په شان ښائسته ينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.', 'زما محبوبې، تۀ لکه د ترضاه د شار په شان شایسته ینه. او، لکه د یروشلم په شان شایسته ینه، او په یو جل لیدو دې ما نه زرګے ورے دېنه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36066, 'Songofsongs 6:5', 'Songofsongs', 6, 5, 'سترګې دې ما نه واړوه، ځکه چې زۀ يې بې‌وسه کړے يمه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', 'سترګې دې ما نه واروه، جکه چې زۀ یې بې‌وسه کرے یمه. ستا زلفی ول ول لکه د چېلو د رمو په شان دینه، چې د جلعاد د غرۀ نه لاندې راکوزیزینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36067, 'Songofsongs 6:6', 'Songofsongs', 6, 6, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه.', 'ستا غاشونه د سپینو ګدو په شان دینه، چې تازه ترې نه وری اخوا شوې وینه، او تازه لمبولے شوے وینه. هر یو غاش دې د بل سره جوره دېنه، یو هم کندم شوے نۀ دېنه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36068, 'Songofsongs 6:7', 'Songofsongs', 6, 7, 'ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', 'ستا اننګی د نقاب شاته لکه د ګلابی انار جلیزینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36069, 'Songofsongs 6:8', 'Songofsongs', 6, 8, 'په شپېتو مَلِکو او په اتيا وينځو کښې او په بې‌شمېره پېغلو کښې،', 'په شپېتو ملکو او په اتیا وینجو کشې او په بې‌شمېره پېغلو کشې،', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36070, 'Songofsongs 6:9', 'Songofsongs', 6, 9, 'خو زۀ به بيا هم خپله ګوګوشتکه خوښومه، زما کامله مينه، د خپلې مور ډېره خوښه ده نه، او د هغه چا ډېره نيازبينه چا چې زيږولې ده نه. پېغلې هغه وينى او د هغې صِفت کوينه، تر دې چې شهزادګۍ او شاهى وينځې د هغې د صِفت سندرې وائينه.', 'خو زۀ به بیا هم خپله ګوګوشتکه خوشومه، زما کامله مینه، د خپلې مور دېره خوشه ده نه، او د هغه چا دېره نیازبینه چا چې زیزولې ده نه. پېغلې هغه وینی او د هغې صفت کوینه، تر دې چې شهزادګی او شاهی وینجې د هغې د صفت سندرې وایینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36071, 'Songofsongs 6:10', 'Songofsongs', 6, 10, '”دا څوک ده چې لکه د سحر د رڼا په شان راوچتيږينه، لکه د سپوږمۍ په شان ښائسته، او د نمر په شان ځليږينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.“', '”دا چوک ده چې لکه د سحر د رنا په شان راوچتیزینه، لکه د سپوزمی په شان شایسته، او د نمر په شان جلیزینه، او په یو جل لیدو دې ما نه زرګے ورے دېنه.“', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36072, 'Songofsongs 6:11', 'Songofsongs', 6, 11, 'زۀ د غوزانو باغ ته لاړمه او وادۍ ته د ګلونو د غوټو سيل ته لاړمه، د انګورو د ځيلو راټوکېدل ووينمه او چې انارو ګلونه کړى دى کۀ نه', 'زۀ د غوزانو باغ ته لارمه او وادی ته د ګلونو د غوتو سیل ته لارمه، د انګورو د جیلو راتوکېدل ووینمه او چې انارو ګلونه کری دی کۀ نه', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36073, 'Songofsongs 6:12', 'Songofsongs', 6, 12, 'زۀ په خپل ځان نۀ پوهېدمه، او د عشق نه رپېدمه لکه چې په شاهى ګاډۍ کښې سور يمه ښځې', 'زۀ په خپل جان نۀ پوهېدمه، او د عشق نه رپېدمه لکه چې په شاهی ګادی کشې سور یمه شجې', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36074, 'Songofsongs 6:13', 'Songofsongs', 6, 13, 'واپس راشه، مونږ ته راواپس شه، اے د شولم پېغلې. واپس راشه، واپس راشه چې مونږ تا دوباره وګورونه. محبوب تاسو د شولم دې پېغلې ته ولې ګورئينه کله چې هغه د ګډېدونکو د دوه صفونو په مينځ کښې ډېره ښائسته ګډيږينه؟', 'واپس راشه، مونز ته راواپس شه، اے د شولم پېغلې. واپس راشه، واپس راشه چې مونز تا دوباره وګورونه. محبوب تاسو د شولم دې پېغلې ته ولې ګوریینه کله چې هغه د ګدېدونکو د دوه صفونو په مینج کشې دېره شایسته ګدیزینه؟', 'NT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(36075, 'Isaiah 25:1', 'Isaiah', 25, 1, 'ای څښتنه، ته یې خدای زما زه به کومه درناوی ستا او ثنا او صفت به کوم ستا د نامه ځکه تا کړي دي ډېر عجیبه کارونه هغه څه چې پلان کړي تا پخوا وو په وفادارۍ دې رسولي هغه سرته', 'ای چشتنه، ته یې خدای زما زه به کومه درناوی ستا او ثنا او صفت به کوم ستا د نامه جکه تا کری دی دېر عجیبه کارونه هغه چه چې پلان کری تا پخوا وو په وفاداری دې رسولی هغه سرته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_001.mp3', 'https://drive.google.com/file/d/1zhCgRYb2l4heY_zedRnbuBQbv_hug81a/preview', 1761237838, 1761237838),
(36076, 'Isaiah 25:2', 'Isaiah', 25, 2, 'تا بدل کړي دي ښارونه کنډوالو باندې او ورانې کړې دې دي ټینګې کلاګانې کومې ماڼۍ چې جوړې کړې وې پردو قومونو هغه شوې ورانې د تل دپاره داسې چې بیا به جوړې نه شي هېڅکله', 'تا بدل کری دی شارونه کندوالو باندې او ورانې کرې دې دی تینګې کلاګانې کومې مانی چې جورې کرې وې پردو قومونو هغه شوې ورانې د تل دپاره داسې چې بیا به جورې نه شی هېچکله', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_002.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=18wnYAnTWw4nnFHHXk8T3VPFiLhAJ9aWi&export=download', 1761237838, 1761237838),
(36077, 'Isaiah 25:3', 'Isaiah', 25, 3, 'نو په دې خاطر به وکړي ثنا او صفت ستا د نړۍ د تکړه قومونو خلک او خلک به تا نه وېره وکړي د ظالمو قومونو په ښارونو کې', 'نو په دې خاطر به وکری ثنا او صفت ستا د نری د تکره قومونو خلک او خلک به تا نه وېره وکری د ظالمو قومونو په شارونو کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_003.mp3', 'https://drive.google.com/file/d/1WBHO1RH4kHGEQV1VjwoDHhlE0UpAP98i/preview', 1761237838, 1761237838),
(36078, 'Isaiah 25:4', 'Isaiah', 25, 4, 'ځکه چې ته د مصیبت په وخت کې یې ساتونکی د غریبو او بې وسه خلکو تا ورکړې ده پناه هغوی ته د توفانونو وخت کې او ورکړی دې دی سیوری د سوځوونکې ګرمۍ په وخت کې د توفان په شان دی پوکی د ظالمانو چې لګیږي په دېوال', 'جکه چې ته د مصیبت په وخت کې یې ساتونکی د غریبو او بې وسه خلکو تا ورکرې ده پناه هغوی ته د توفانونو وخت کې او ورکری دې دی سیوری د سوجوونکې ګرمی په وخت کې د توفان په شان دی پوکی د ظالمانو چې لګیزی په دېوال', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_004.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1hLmgYBwOtiFSCoPM2xJd_XJQPn90ADmY&export=download', 1761237838, 1761237838),
(36079, 'Isaiah 25:5', 'Isaiah', 25, 5, 'لکه ګرمي د صحرا چې وچوي ځمکه خو ای څښتنه، غلي کوې ته اوازونه د پردو قومونو داسې لکه ورېځ چې سړوي ډېره ګرمي نو غلې کوې ته همدارنګه سندره د ظالمو خلکو', 'لکه ګرمی د صحرا چې وچوی جمکه خو ای چشتنه، غلی کوې ته اوازونه د پردو قومونو داسې لکه ورېج چې سروی دېره ګرمی نو غلې کوې ته همدارنګه سندره د ظالمو خلکو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_005.mp3', 'https://drive.google.com/uc?id=1qnKR1sjUGDrssSgv_DAg6zl3H9p97t2O&export=download', 1761237838, 1761237838),
(36080, 'Isaiah 25:6', 'Isaiah', 25, 6, 'مطلق قادر څښتن به د صهیون په غره باندې د نړۍ ټولو قومونو ته د خوندورو خوراکونو او د انګورو د ښو زړو شرابو مېلمستیا تیاره کړي.', 'مطلق قادر چشتن به د صهیون په غره باندې د نری تولو قومونو ته د خوندورو خوراکونو او د انګورو د شو زرو شرابو مېلمستیا تیاره کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_006.mp3', 'https://drive.google.com/file/d/1Xq1-boZOhtVLdpfAtYXgEoNEzsL4k1uV/preview', 1761237838, 1761237838),
(36081, 'Isaiah 25:7', 'Isaiah', 25, 7, 'دلته به هغه د غم څادر لېرې کړي چې په ټولو خلکو باندې هوار دی او د قومونو څخه به هغه کفن لېرې کړي چې په هغوی باندې پروت دی.', 'دلته به هغه د غم چادر لېرې کری چې په تولو خلکو باندې هوار دی او د قومونو چخه به هغه کفن لېرې کری چې په هغوی باندې پروت دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_007.mp3', 'https://drive.google.com/uc?id=1h8XEo75h3T8bF_UMLWqC-e5rAbClwLWW&export=download', 1761237838, 1761237838),
(36082, 'Isaiah 25:8', 'Isaiah', 25, 8, 'څښتن تعالی به د تل دپاره مرګ لېرې کړي! هغه به د هرچا د سترګو اوښکې وچې کړي او د خپلو خلکو هغه رسوایي او بې عزتي چې هغوی په ټوله نړۍ کې ورسره مخامخ دي، لېرې کړي. دا په خپله څښتن ویلي دي.', 'چشتن تعالی به د تل دپاره مرګ لېرې کری! هغه به د هرچا د سترګو اوشکې وچې کری او د خپلو خلکو هغه رسوایی او بې عزتی چې هغوی په توله نری کې ورسره مخامخ دی، لېرې کری. دا په خپله چشتن ویلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_008.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1Xi6HXOKk26h_gNo7_Q0M7ehmGen2N8YC&export=download', 1761237838, 1761237838),
(36083, 'Isaiah 25:9', 'Isaiah', 25, 9, 'په هغه ورځ به خلک داسې وایي: «وګورئ، هغه زمونږ خدای دی چې ورته سترګې په لاره وو او مونږ یې ژغورلي یو. هغه څښتن دی چې مونږ د هغه نه هیله لرله، نو په دې خاطر چې هغه مونږ ژغوري، باید د خوشحالۍ جشن جوړ کړو.»', 'په هغه ورج به خلک داسې وایی: «وګوری، هغه زمونز خدای دی چې ورته سترګې په لاره وو او مونز یې ژغورلی یو. هغه چشتن دی چې مونز د هغه نه هیله لرله، نو په دې خاطر چې هغه مونز ژغوری، باید د خوشحالی جشن جور کرو.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah025_verse_009.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1SNUGg0DlDenvQ-w7NFp88Vjh98wSUhyS&export=download', 1761237838, 1761237838),
