(36150, 'Numbers 9:20', 'Numbers', 9, 20, 'کله کله به ورېځ په خېمې باندې یوازې د یو څو ورځو دپاره پاتې کېدله، په هر حال کې به هغوی د څښتن د حکم سره سم په کمپ کې پاتې کېدل یا به یې کډه کوله.', 'کله کله به ورېج په خېمې باندې یوازې د یو چو ورجو دپاره پاتې کېدله، په هر حال کې به هغوی د چشتن د حکم سره سم په کمپ کې پاتې کېدل یا به یې کده کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_9_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36151, 'Numbers 9:21', 'Numbers', 9, 21, 'کله کله ورېځ یوازې د ماښام څخه تر سهاره پورې پاتې کېدله، څنګه به چې ورېځ پورته شوه، هغوی به کډه کوله. هرکله چې ورېځ پورته کېدله، هغوی کډه کوله.', 'کله کله ورېج یوازې د ماشام چخه تر سهاره پورې پاتې کېدله، چنګه به چې ورېج پورته شوه، هغوی به کده کوله. هرکله چې ورېج پورته کېدله، هغوی کده کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_9_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(36152, 'Numbers 9:22', 'Numbers', 9, 22, 'که دا به دوه ورځې، یوه میاشت یا به ډېره موده وه، ترڅو چې په خېمې باندې به ورېځ وه هغوی کډه نه کوله. خو کله چې ورېځ پورته کېدله، هغوی به کډه کوله.', 'که دا به دوه ورجې، یوه میاشت یا به دېره موده وه، ترچو چې په خېمې باندې به ورېج وه هغوی کده نه کوله. خو کله چې ورېج پورته کېدله، هغوی به کده کوله.', 'OT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
